fn bool_to_trait(b: bool) -> impl Trait {
    b
}

fn mk_trait(b: bool) -> Box<dyn Trait> {
    if b {
        Box::new(b)
    } else {
        Box::new(0)
    }
}

fn mk_into<U, V, T: Into<V> + 'static, W: Into<V> + 'static>(
    b: bool,
    x: T,
    y: W,
) -> Box<dyn Into<V>> {
    if b {
        Box::new(x)
    } else {
        Box::new(y)
    }
}

fn dyn_closure(_: impl Trivial) {
    let f = |x: u32| -> u32 { x };
}

impl Trait for u32 {
    fn get(&self) -> u32 {
        *self
